import{_ as n,o as a,c as e,a4 as t}from"./chunks/framework.BBs01uty.js";const u=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/architecture.md","filePath":"agent-cli/architecture.md"}'),o={name:"agent-cli/architecture.md"};function p(c,s,d,l,i,r){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><blockquote><p>读代码前的地图。看完你应该能回答：一个按键从按下到产生 LLM 回答，经过了哪些模块； 以及哪些约束是<strong>不能碰</strong>的。</p></blockquote><h2 id="_1-分层" tabindex="-1">1. 分层 <a class="header-anchor" href="#_1-分层" aria-label="Permalink to &quot;1. 分层&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 入口 / 编排      index.ts (1615)                              │</span></span>
<span class="line"><span>│   参数解析 · system prompt 组装 · 命令表 · ! 模式 · 退出收尾    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>        │                    │                    │</span></span>
<span class="line"><span>        ▼                    ▼                    ▼</span></span>
<span class="line"><span>┌───────────────┐  ┌──────────────────┐  ┌────────────────────┐</span></span>
<span class="line"><span>│ Agent 层      │  │ 交互原语层        │  │ UI 层（自研 TUI）   │</span></span>
<span class="line"><span>│ agent/loop.ts │  │ interaction.ts   │  │ ui/tui.ts (2099)   │</span></span>
<span class="line"><span>│ models.ts     │  │ ui/overlay*.ts   │  │ input-buffer.ts    │</span></span>
<span class="line"><span>└───────┬───────┘  └────────┬─────────┘  │ status-machine.ts  │</span></span>
<span class="line"><span>        │                   │            │ task-panel/fullscreen│</span></span>
<span class="line"><span>        ▼                   ▼            │ completion-menu …   │</span></span>
<span class="line"><span>┌─────────────────────────────────────┐   └────────────────────┘</span></span>
<span class="line"><span>│ 工具层   tools/index.ts（门面）      │</span></span>
<span class="line"><span>│   registry.ts(1065, 15 个工具)      │</span></span>
<span class="line"><span>│   executor.ts · truncate.ts         │</span></span>
<span class="line"><span>└───────────┬─────────────────────────┘</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 横切能力                                                      │</span></span>
<span class="line"><span>│  权限 permissions.ts · project-permissions.ts                 │</span></span>
<span class="line"><span>│  Hook   hooks.ts                                              │</span></span>
<span class="line"><span>│  后台任务 tasks.ts                                            │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>            ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 基础设施                                                      │</span></span>
<span class="line"><span>│  config.ts · session.ts · user-config.ts · images.ts          │</span></span>
<span class="line"><span>│  clipboard.ts · editor.ts · commands.ts · skills.ts           │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>分层铁律</strong>（各模块头注释反复强调）：<code>ui/*</code>、<code>commands.ts</code>、<code>task-panel.ts</code> 等<strong>纯逻辑模块不碰 <code>process.stdin/stdout</code></strong>，只把&quot;该画什么 / 状态怎么变&quot;返回给 <code>tui.ts</code>，由它统一写终端。这是它们能被 Vitest 直测的前提。</p><h2 id="_2-两条主数据流" tabindex="-1">2. 两条主数据流 <a class="header-anchor" href="#_2-两条主数据流" aria-label="Permalink to &quot;2. 两条主数据流&quot;">​</a></h2><h3 id="流-a-交互输入-→-提交" tabindex="-1">流 A：交互输入 → 提交 <a class="header-anchor" href="#流-a-交互输入-→-提交" aria-label="Permalink to &quot;流 A：交互输入 → 提交&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>keypress</span></span>
<span class="line"><span>  → tui.ts 路由（先浮层、再命令键、再普通输入）</span></span>
<span class="line"><span>  → input-buffer.ts（原子数组模型：图片/粘贴占位符不可被拆开）</span></span>
<span class="line"><span>  → onEnter(content)</span></span>
<span class="line"><span>  → index.ts handleSubmit</span></span>
<span class="line"><span>       ├─ 斜杠命令（commands.ts 的命令表）</span></span>
<span class="line"><span>       ├─ ! 前缀 → runBangCommand（前台 bash；Ctrl+B 转后台）</span></span>
<span class="line"><span>       └─ 普通消息 → runTurn → 进入流 B</span></span></code></pre></div><h3 id="流-b-llm-→-工具-→-回传-agent-循环" tabindex="-1">流 B：LLM → 工具 → 回传（Agent 循环） <a class="header-anchor" href="#流-b-llm-→-工具-→-回传-agent-循环" aria-label="Permalink to &quot;流 B：LLM → 工具 → 回传（Agent 循环）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>runTurn(messages, ui, deps)</span></span>
<span class="line"><span>  → agent/loop.ts  (stream)</span></span>
<span class="line"><span>       事件：llm_start · reasoning · token · tool_start · tool_end · error</span></span>
<span class="line"><span>  → index.ts handle(event)</span></span>
<span class="line"><span>       ├─ token / reasoning → TUI 渲染（appendToLast / updateThinking）</span></span>
<span class="line"><span>       └─ tool_start → tools/executor.ts</span></span>
<span class="line"><span>              ├─ permissions.ts 判定（纯函数 decidePermission）</span></span>
<span class="line"><span>              │    ├─ 放行 → 执行</span></span>
<span class="line"><span>              │    ├─ ask   → interaction.ts 弹审批（与 ask_user 同一路径）</span></span>
<span class="line"><span>              │    └─ forced→ 强制审批（--yes 也拒绝）</span></span>
<span class="line"><span>              └─ hooks.ts  PreToolUse（可 block）/ PostToolUse</span></span>
<span class="line"><span>       → 结果经 truncate.ts 双阈值截断 → 作为 tool 消息回传 → 下一轮</span></span>
<span class="line"><span>  → 无 tool_calls → 结束</span></span></code></pre></div><p>关键点：流式响应里的 <code>tool_calls</code> 是<strong>分片返回</strong>的（函数名与参数被拆成多个 delta），必须按 index 累积拼接后才能解析参数 —— <code>agent/loop.ts</code>。</p><h3 id="流-c-退出收尾" tabindex="-1">流 C：退出收尾 <a class="header-anchor" href="#流-c-退出收尾" aria-label="Permalink to &quot;流 C：退出收尾&quot;">​</a></h3><p><code>Ctrl+C</code>（两次）/ <code>Ctrl+D</code> / <code>/exit</code> → <code>ui/exit-guard.ts</code> 状态机 → <code>index.ts</code> 的 <code>createShutdown</code>： <code>cancelAll → releaseLock → killAll → ui.exit → 打印被终止清单 → bye → exit</code>。<strong>顺序有 AC 约束，不可调换</strong>。</p><h2 id="_3-磁盘布局" tabindex="-1">3. 磁盘布局 <a class="header-anchor" href="#_3-磁盘布局" aria-label="Permalink to &quot;3. 磁盘布局&quot;">​</a></h2><p>默认根目录 <code>~/.agent-cli</code>（环境变量 <code>AGENT_CLI_DIR</code> 可整体覆盖，测试靠它隔离）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.agent-cli/</span></span>
<span class="line"><span>├── config.json          用户配置：当前模型 / 思考等级（/model 写入）</span></span>
<span class="line"><span>├── prompt.md            用户自定义根提示词（存在则替换内置默认值）</span></span>
<span class="line"><span>├── memory/memory.md     用户长期记忆（启动时拼进 system prompt）</span></span>
<span class="line"><span>├── session/</span></span>
<span class="line"><span>│   └── &lt;workspace-id&gt;/  每个工作目录一个（workspace-id = cwd 的 sha256 前 16 位）</span></span>
<span class="line"><span>│       ├── session-&lt;unixms&gt;.json   会话消息</span></span>
<span class="line"><span>│       └── session-&lt;unixms&gt;.lock   会话锁（记录持有进程 pid）</span></span>
<span class="line"><span>├── images/              粘贴/提交的图片（单图 ≤10MB，按 mtime 保留最新 100 张）</span></span>
<span class="line"><span>└── tasks/               后台任务日志 &lt;task-id&gt;.log</span></span></code></pre></div><p>仓库内（<strong>项目级，随仓库走</strong>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;仓库根&gt;/.agent-cli/</span></span>
<span class="line"><span>├── permissions.json     项目级 allow 规则（&quot;永远允许&quot;写入，需信任才生效）</span></span>
<span class="line"><span>└── hooks.json           项目级 Hook 配置（需信任才加载）</span></span></code></pre></div><p><code>&lt;仓库根&gt;</code> = <code>resolveRepoRoot(cwd)</code>（git 仓库取仓库根，<strong>非 git 回落 cwd</strong>）—— 见 <code>src/project-permissions.ts</code> 的 <code>resolveRepoRoot</code> / <code>permissionsFilePath</code>。</p><blockquote><p>⚠️ 会话文件<strong>不存 system prompt</strong>：恢复时用当前提示词重新组装，避免提示词改版后旧会话用过期的 system（也保护前缀稳定性，见不变量 1）。 图片不内联 base64：写盘前 <code>stripImages</code> 换成 <code>image_ref</code>，恢复时 <code>hydrateImages</code> 还原。</p></blockquote><h2 id="_4-十条硬不变量-改代码前必读" tabindex="-1">4. 十条硬不变量（改代码前必读） <a class="header-anchor" href="#_4-十条硬不变量-改代码前必读" aria-label="Permalink to &quot;4. 十条硬不变量（改代码前必读）&quot;">​</a></h2><p>踩中任何一条都是&quot;看起来能跑、实际埋雷&quot;。</p><table tabindex="0"><thead><tr><th>#</th><th>不变量</th><th>在哪 / 为什么</th></tr></thead><tbody><tr><td>1</td><td><strong>前缀稳定性</strong>：system prompt 前部不可改写</td><td>Ollama 支持前缀 KV 缓存，实测同前缀 prefill <strong>8587ms → 192ms（44×）</strong>。易变内容（技能索引、memory、目录树）一律作为<strong>对话消息</strong>追加。断言见 <code>index.e2e.test.ts</code> 的 AC-59。也正因如此，Hook <strong>明确不做 <code>SessionStart</code></strong>（它会改写已发送内容）。</td></tr><tr><td>2</td><td><strong>布局唯一公式</strong> <code>contentRowsFor</code> / <code>reservedRowsFor</code></td><td><code>contentRowsFor(rows, floatingRows) = max(1, rows - INPUT_ROWS(5) - STATUS_ROWS(1) - reservedRowsFor(floatingRows))</code>；<code>reservedRowsFor = PERSISTENT_ROWS(1) + max(0, floatingRows)</code>。<strong>禁止再硬编码 <code>24-5-1-3</code></strong> 之类算术。见 <code>src/ui/tui.ts:216/225</code>。</td></tr><tr><td>3</td><td><strong>浮层高度恒定（V-5）</strong></td><td>浮层/面板/菜单高度在生命周期内<strong>不能变</strong>；一变就触发整区重建（清屏 + 清 scrollback），是本项目最脆弱的路径。故面板打开时<strong>只刷新既有条目内容、不增删条目</strong>。</td></tr><tr><td>4</td><td><strong>唯一定时器</strong></td><td>全项目只有一个 <code>Ticker</code>（<code>status-machine.ts</code>），帧间隔 <code>FRAME_INTERVAL_MS = 100</code>；idle（非 animating）<strong>必须停止</strong>（AC-4）。单个 tick 重绘 ≤3 行（AC-65）。</td></tr><tr><td>5</td><td><strong>单位口径同源</strong></td><td>行数只认 <code>countLines()</code>、截断只认 <code>truncateToolOutput()</code>；阈值、标注、&quot;输出 N 行&quot;三者必须同源（lesson 012），曾因两套计数出过 bug。见 <code>src/tools/truncate.ts</code>。</td></tr><tr><td>6</td><td><strong>不可信文本必须先净化</strong></td><td>任何外部文本（LLM 输出、工具参数/输出、仓库文件、用户输入、会话文件）进终端前过 <code>sanitizeForTerminal</code>，且<strong>只能落在内容边界</strong>（不能落渲染层，否则会剥掉自家样式）。规范见 <code>knowledge/standards/terminal-output-safety.md</code>。</td></tr><tr><td>7</td><td><strong>权限 I-3 不变式</strong></td><td><code>ask &amp;&amp; forced</code> 必须在任何授权/豁免判定<strong>之前</strong>短路；危险命令走 <code>forced</code>，<code>--yes</code> 也不得自动批准。见 <code>src/permissions.ts</code>。</td></tr><tr><td>8</td><td><strong>交互唯一分派路径（AC-27）</strong></td><td>权限审批、Hook 信任、LLM 的 <code>ask_user</code> 走<strong>同一套</strong>交互原语（<code>interaction.ts</code> + <code>ui/overlay*.ts</code>），不许各写一份胶水。</td></tr><tr><td>9</td><td><strong>会话锁与 workspace 隔离</strong></td><td>编辑会话前 <code>acquireSessionLock</code>；异常退出残留的锁靠 pid 存活探测判过期并接管。不同工作目录的会话互不干扰。</td></tr><tr><td>10</td><td><strong>单模型常驻</strong></td><td>本机 Metal 预算 10.7 GiB 装不下两个 8B 模型 → 视觉能力（<code>view_image</code>）与主模型同源；<code>/model</code> 切换是改配置而非并行加载。</td></tr></tbody></table><h2 id="_5-几个-为什么这么设计" tabindex="-1">5. 几个&quot;为什么这么设计&quot; <a class="header-anchor" href="#_5-几个-为什么这么设计" aria-label="Permalink to &quot;5. 几个&quot;为什么这么设计&quot;&quot;">​</a></h2><ul><li><strong>TUI 自研而不用 Ink/React</strong>：直接用 DECSTBM（<code>ESC[top;bottom r</code>）把屏幕切成&quot;固定区 + 可滚动内容区&quot;，流式输出不会顶乱界面，滚动行为更接近原生终端；同时渲染逻辑变成纯数据（行数组）可断言。代价是要自己处理宽字符、wrap-pending、resize 重排。</li><li><strong>输入框用&quot;原子数组&quot;而非字符串</strong>：需求要求图片/粘贴占位符<strong>一次 backspace 整体删除</strong>，且图片在消息里的位置必须与文本中的位置一致；原子数组让原子性由数据结构天然保证（<code>src/ui/input-buffer.ts</code>）。</li><li><strong>状态机外置</strong>：状态栏此前散落在 <code>index.ts</code> 的 6 处 <code>setStatus</code> 调用，没有单一状态源；抽成 <code>status-machine.ts</code> 后迁移表可单测穷举（AC-1）。</li><li><strong>工具层做薄门面</strong>：<code>tools/index.ts</code> 只聚合；定义与实现集中在 <code>registry.ts</code>，执行编排在 <code>executor.ts</code>，规模口径在 <code>truncate.ts</code>。</li><li><strong>后台任务用事件驱动</strong>：<code>tasks.ts</code> 全部走 <code>child.on(&#39;exit&#39;)</code> / <code>onChange</code> 回调，<strong>不引定时器轮询</strong>（<code>waitForExit</code> 复用 <code>exitWaiters</code>）。</li></ul>`,25)])])}const h=n(o,[["render",p]]);export{u as __pageData,h as default};
